document.addEventListener("DOMContentLoaded",function(){function removeRedundantSummary(){const sidebar=document.querySelector(".wc-block-components-sidebar");if(!sidebar)return;const customCard=sidebar.querySelector(".Gstore-order-summary-card");if(!customCard)return;const potentialDuplicates=Array.from(sidebar.children).filter(child=>{if(child.contains(customCard)||child===customCard)return false;return child.querySelector(".wc-block-components-checkout-order-summary__title")!==null});potentialDuplicates.forEach(duplicate=>{duplicate.remove()})}removeRedundantSummary();const observer=new MutationObserver(mutations=>{removeRedundantSummary()});const checkoutWrapper=document.querySelector(".wp-block-woocommerce-checkout");if(checkoutWrapper){observer.observe(checkoutWrapper,{childList:true,subtree:true})}});
